package dev.homecontrol.app;
import org.json.*;
import java.nio.file.*;
import java.util.*;

public final class PanelLayoutTest {
 static int count;static void check(boolean value){count++;if(!value)throw new AssertionError("panel layout "+count);}
 public static void main(String[] args)throws Exception{
  JSONArray fixtures=new JSONArray(new String(Files.readAllBytes(Paths.get("tests/fixtures/panel-models.json")),java.nio.charset.StandardCharsets.UTF_8));
  for(int i=0;i<fixtures.length();i++){JSONObject d=fixtures.getJSONObject(i);if(!PanelLayout.compact(d))continue;JSONArray props=d.getJSONArray("capabilities");List<JSONObject> main=PanelLayout.main(d,props);Set<String> used=new HashSet<>();for(JSONObject p:main){check(p.optBoolean("writable"));check(!PanelLayout.metric(p));used.add(p.getString("key"));if(PanelLayout.power(d))check("on".equals(p.getString("name")));}check(main.size()==(PanelLayout.power(d)?2:5));for(PanelLayout.Group g:PanelLayout.groups(d,props,used))for(JSONObject p:g.properties){check(!used.contains(p.getString("key")));check(!PanelLayout.metric(p));}String line=PanelLayout.metrics(d,props);check(!line.contains("\n"));check(line.contains("—"));if(PanelLayout.climate(d)){Set<String> names=new HashSet<>();for(JSONObject p:main)names.add(p.optString("name"));check(names.containsAll(Arrays.asList("on","mode","target-temperature","vertical-swing","fan-level")));}}
  JSONObject metric=new JSONObject().put("key","p:5:1").put("name","power-consumption").put("value",1000000);check("6 kWh".equals(PanelLayout.formatMetric("chuangmi.plug.212a01",metric)));metric.put("key","p:11:1").put("value",123);check("1.23 kWh".equals(PanelLayout.formatMetric("cuco.plug.v3",metric)));metric.put("key","p:5:6").put("value",1001);check("10.01 W".equals(PanelLayout.formatMetric("chuangmi.plug.212a01",metric)));
  CycleTask task=new CycleTask("30;15;1,3,5;60;1380;8");check("45;20;1,3,5;60;1380;8".equals(task.encode(45,20,60,1380)));for(String invalid:new String[]{"30;15;1,1;60;1380;0","0;15;;60;1380;0","30;15;;60;60;0","unknown","30;15;;0;1440;0"}){boolean rejected=false;try{new CycleTask(invalid);}catch(java.io.IOException expected){rejected=true;}check(rejected);}
  for(int i=0;i<fixtures.length();i++){JSONObject d=fixtures.getJSONObject(i);if(!CameraPolicy.supported(d.optString("model")))continue;JSONArray items=CameraStorage.items(d);check(items.length()>=5);for(int j=0;j<items.length();j++){JSONObject p=items.getJSONObject(j);check(!"dialog-ejected".equals(p.optString("name")));check(!CameraStorage.title(p).isEmpty());if("status".equals(p.optString("name")))check(p.getInt("siid")==("xiaomi.camera.c302".equals(d.optString("model"))?3:4));}}
  check(CameraStorage.items(new JSONObject().put("model","unknown.camera")).length()==0);
  check("nas_get_config".equals(CameraNas.method("chuangmi.camera.069a01","camera.nas.get")));check(CameraNas.params("camera.nas.get",new JSONObject()) instanceof JSONObject);check(CameraNas.params("camera.nas.scan",new JSONObject()) instanceof JSONArray);for(String model:new String[]{"unknown.camera","chuangmi.camera.039a01"}){boolean rejected=false;try{CameraNas.method(model,"camera.nas.get");}catch(java.io.IOException expected){rejected=true;}check(rejected);}boolean rejected=false;try{CameraNas.method("xiaomi.camera.c302","camera.nas.reset");}catch(java.io.IOException expected){rejected=true;}check(rejected);JSONObject share=new JSONObject().put("type",1).put("addr",1234).put("name","test").put("group","WORKGROUP").put("dir","video").put("user","").put("pass","");JSONObject settings=new JSONObject().put("state",3).put("sync_interval",300).put("video_retention_time",7776000).put("share",share);check(((JSONObject)CameraNas.params("camera.nas.set",settings)).getJSONObject("share").getLong("addr")==1234);for(String key:new String[]{"type","addr","dir"}){JSONObject bad=new JSONObject(share.toString());bad.remove(key);rejected=false;try{CameraNas.params("camera.nas.set",new JSONObject(settings.toString()).put("share",bad));}catch(Exception expected){rejected=true;}check(rejected);}check(CameraNas.config(new JSONObject().put("result",settings)).getInt("state")==3);
  JSONObject cycleProperty=new JSONObject().put("key","p:5:2").put("title","data-value").put("value","30;20;1,3,5;60;1380;0");check("循环时间".equals(PanelLayout.fieldTitle("cuco.plug.v3",cycleProperty)));check(!PanelLayout.summary("cuco.plug.v3",cycleProperty).contains(";"));check(PanelLayout.summary("cuco.plug.v3",cycleProperty).contains("30 分钟"));check(PanelLayout.fieldTitle("chuangmi.plug.212a01",new JSONObject().put("title","开启时长").put("unit","seconds")).endsWith("（秒）"));
  System.out.println(count+" panel grouping, telemetry, cycle preservation and storage mapping checks passed");
 }
}
